// Le navigateur n'envoie que l'id et la quantitÃ© : ici on vÃ©rifie la forme du panier,
// les noms et prix viennent ensuite de la table app.products (nÅ“ud suivant).
const MAX_QUANTITY = 10;
const SITE = 'https://franck93-sel.github.io/sunglasses-shop/';
// Retours Stripe autorisÃ©s : le site en ligne et le dÃ©veloppement local.
const ALLOWED_RETURN = /^(https:\/\/franck93-sel\.github\.io\/sunglasses-shop\/|http:\/\/(localhost|127\.0\.0\.1)(:\d+)?\/)/;

const input = $input.first().json;
const body = input.body || input;
const raw = Array.isArray(body.items) ? body.items : [];

if (raw.length === 0 || raw.length > 20) {
  throw new Error('Panier vide ou invalide.');
}

const items = raw.map((item) => {
  const id = Number(item.id);
  const quantity = item.quantity === undefined ? 1 : Number(item.quantity);
  if (!Number.isInteger(id) || id < 1) throw new Error('Produit inconnu dans le panier.');
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QUANTITY) {
    throw new Error('QuantitÃ© invalide dans le panier.');
  }
  return { id, quantity };
});

function returnUrl(url, fallback) {
  return typeof url === 'string' && ALLOWED_RETURN.test(url) ? url : fallback;
}
const email = typeof body.email === 'string' ? body.email.trim() : '';

return [{
  json: {
    items,
    productIds: [...new Set(items.map((i) => i.id))],
    successUrl: returnUrl(body.successUrl, SITE + 'checkout-success.html'),
    cancelUrl: returnUrl(body.cancelUrl, SITE + 'checkout.html'),
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : '',
  },
}];

// Noms et prix : uniquement ceux de la base (produits actifs), jamais ceux du navigateur.
const cart = $('Valider Panier').first().json;
const catalog = new Map(
  $input.all()
    .map((i) => i.json)
    .filter((row) => row.id !== undefined && row.id !== null)
    .map((row) => [Number(row.id), row])
);

const params = [];
function addParam(key, value) {
  params.push(encodeURIComponent(key) + '=' + encodeURIComponent(value));
}

cart.items.forEach((item, idx) => {
  const product = catalog.get(item.id);
  if (!product) throw new Error('Produit inconnu ou indisponible dans le panier.');
  addParam(`line_items[${idx}][price_data][currency]`, 'eur');
  addParam(`line_items[${idx}][price_data][unit_amount]`, Math.round(Number(product.price) * 100));
  addParam(`line_items[${idx}][price_data][product_data][name]`, product.name);
  addParam(`line_items[${idx}][quantity]`, item.quantity);
});

addParam('mode', 'payment');
addParam('success_url', cart.successUrl);
addParam('cancel_url', cart.cancelUrl);
if (cart.email) addParam('customer_email', cart.email);

return [{ json: { bodyString: params.join('&') } }];
